import subprocess
source="import json,collections\nfrom pathlib import Path\nimport rosbag2_py\nfrom rclpy.serialization import deserialize_message\nfrom rosidl_runtime_py.utilities import get_message\nbase=Path('/root/gpufree-data/semantic/output/native_scene18_capture_005/capture_20261012_111643/delivery_300')\ngroups=[json.loads(x) for x in (base/'groups.jsonl').read_text().splitlines()]\nby={round(g['native_time_s']*1e9)+offset:g['group'] for g in groups for offset in (-2,-1,0,1,2)}\nr=rosbag2_py.SequentialReader();r.open(rosbag2_py.StorageOptions(uri=str(base/'bag'),storage_id='mcap'),rosbag2_py.ConverterOptions('',''))\nmeta=r.get_all_topics_and_types();topics=[t.name for t in meta if t.name.startswith('/lidar/') or t.name in ('/tf','/clock')];types={t.name:get_message(t.type) for t in meta}\nr.set_filter(rosbag2_py.StorageFilter(topics=topics));order=[]\nwhile r.has_next():\n topic,data,recorded=r.read_next();m=deserialize_message(data,types[topic])\n st=m.clock if topic=='/clock' else m.transforms[0].header.stamp if topic=='/tf' else m.header.stamp\n order.append(by[st.sec*10**9+st.nanosec])\nbad=[i//16 for i in range(0,len(order),16) if len(set(order[i:i+16]))!=1 or order[i]!=i//16]\nprint(json.dumps({'filtered_messages':len(order),'groups':len(groups),'bad_burst16_blocks':bad,'lidar_qos':str(next(t.offered_qos_profiles for t in meta if t.name.startswith('/lidar/')))}))\n"
r=subprocess.run(['bash','--noprofile','--norc','-c','source /opt/ros/jazzy/setup.bash && exec /usr/bin/python3 -'],input=source,text=True,capture_output=True,timeout=90)
print(r.stdout);print(r.stderr);raise SystemExit(r.returncode)
